<script setup lang="ts">
const question=ref('Come sono cambiati il mio volume e il mio recupero nelle ultime sei settimane?')
const provider=ref('openai'),busy=ref(false),message=ref(''),answer=ref<any>(null),conversation=ref<any[]>([])
const {data:ctx,error}=await useFetch<any>('/api/platform/coach')
const examples=['Come sono cambiati volume e recupero nelle ultime sei settimane?','Come si presenta la mia HRV rispetto alla baseline personale e al sonno?','Che cosa mostrano i lap da 100 m nelle ultime cinque sedute confrontabili?','Il programma confermato è coerente con le disponibilità e i volumi recenti?']
const fact=(id:string)=>answer.value?.context.facts.find((f:any)=>f.fact_id===id)
async function ask(){busy.value=true;message.value='';try{
 const r=await $fetch<any>('/api/platform/coach',{method:'POST',timeout:330000,retry:0,headers:{'x-csrf-token':ctx.value?.csrf||''},body:{question:question.value,provider:provider.value}})
 answer.value=r;conversation.value.unshift(r)
}catch(e:any){message.value=e.data?.error||'Risposta non disponibile. I dati locali restano consultabili.'}finally{busy.value=false}}
const sections:any={what_is_working:'Cosa sta funzionando',what_needs_attention:'Cosa osservare',actions_next_7_days:'Decisioni per i prossimi giorni',direction_next_21_days:'Direzione del lavoro',scenario_next_42_days:'Scenario del blocco',what_to_avoid:'Cosa evitare',questions_for_athlete:'Informazioni che mancano al coach'}
</script>
<template><div class="space-y-6 max-w-[1500px] mx-auto w-full pb-10"><div><p class="eyebrow">INTERPRETAZIONE AI · EVIDENZE CALCOLATE DAL BACKEND</p><h1 class="text-3xl font-bold mt-2">Il coach conosce il tuo storico.</h1><p class="muted mt-2">Nuoto, sonno, HRV, carico, disponibilità e piani confermati nella stessa analisi.</p></div><UAlert v-if="error" color="error" title="Contesto analitico non disponibile"/><div class="grid lg:grid-cols-3 gap-5"><div class="panel lg:col-span-2 space-y-4"><h2 class="font-semibold">La tua domanda</h2><textarea v-model="question" rows="4" aria-label="Domanda al coach" class="w-full"/><div class="flex flex-wrap gap-3"><select v-model="provider" aria-label="Provider"><option value="openai">OpenAI · Codex · account ChatGPT</option><option value="local">Lettura locale · regole deterministiche</option></select><UButton @click="ask" :loading="busy" :disabled="!ctx||!question.trim()">Analizza</UButton></div><p class="muted" v-if="busy">Il coach sta leggendo le evidenze. Le richieste OpenAI possono richiedere alcuni minuti; la risposta viene controllata prima di essere mostrata.</p><p role="status" class="text-amber-300 text-sm">{{message}}</p><div class="flex flex-wrap gap-2"><button v-for="example in examples" class="rounded-lg border border-zinc-800 px-3 py-2 text-left text-xs text-zinc-400 hover:text-green-400" @click="question=example">{{example}}</button></div></div><div class="panel space-y-4"><p class="eyebrow">CONTESTO E PRIVACY</p><p class="text-sm">{{ctx?.context.facts.length||'—'}} fatti con periodo e copertura. Ultima osservazione: {{ctx?.context.observation_date||'—'}}.</p><p class="muted">OpenAI riceve il pacchetto analitico che hai autorizzato: metriche, obiettivi, disponibilità, feedback e domanda. Chiavi, FIT originali e coordinate GPS sono esclusi. Il modello non può usare shell, browser, plugin o MCP per leggere altri dati.</p><p class="muted">Ogni domanda ricostruisce il contesto dai dati attuali. Le risposte sono interpretazioni, conservate localmente e separate dai fatti misurati.</p><NuxtLink to="/calendar" class="block text-green-400 text-sm">Aggiorna obiettivi e disponibilità →</NuxtLink><p v-if="ctx&&!ctx.openai_available" class="text-amber-300 text-sm">Codex non trovato. La lettura locale rimane disponibile.</p></div></div><div v-if="answer" class="space-y-5"><div class="panel"><UBadge>{{answer.answer.model}}</UBadge><p class="muted mt-3">{{answer.context.observation_date}} · confidenza {{answer.answer.confidence}} · {{answer.context.digest}}</p><h2 class="text-xl font-semibold mt-4">{{answer.answer.verdict}}</h2><p class="text-green-400 mt-3">{{answer.answer.primary_focus}}</p><div class="grid md:grid-cols-2 gap-x-8"><section v-for="(label,key) in sections" v-show="answer.answer[key]?.length" class="mt-6"><h3 class="eyebrow mb-3">{{label}}</h3><p v-for="text in answer.answer[key]" class="text-sm text-zinc-300 mt-2 leading-relaxed">{{text}}</p></section></div><p v-if="answer.answer.next_check" class="muted mt-6">Prossima verifica: {{answer.answer.next_check}}</p><p v-for="text in answer.answer.boundary" class="muted mt-3">{{text}}</p></div><div class="panel"><h2 class="font-semibold mb-4">Evidenze citate dal coach</h2><div class="grid md:grid-cols-2 gap-3"><div v-for="id in answer.answer.why" class="border border-zinc-800 rounded-xl p-3 text-sm"><p class="font-semibold">{{fact(id)?.label||id}}</p><p class="mt-2">{{fact(id)?.display}} {{fact(id)?.unit}}</p><p class="muted mt-2">{{fact(id)?.window}} · {{fact(id)?.availability}} · n={{fact(id)?.n??'—'}}/{{fact(id)?.expected_n??'—'}}</p><NuxtLink v-if="answer.sources[id]" :to="'/activity/'+answer.sources[id].activity_id" class="text-green-400 block mt-2">Apri la seduta del {{answer.sources[id].date}} →</NuxtLink></div></div></div></div><details v-if="ctx" class="panel"><summary class="font-semibold text-green-400 cursor-pointer">Fatti, periodi e copertura usati nella risposta</summary><p class="muted mt-4">Anteprima del pacchetto. Non richiede l’invio a OpenAI.</p><div class="table-wrap mt-4"><table><thead><tr><th>Evidenza</th><th>Valore</th><th>Unità</th><th>Periodo</th><th>Copertura</th><th>Disponibilità</th></tr></thead><tbody><tr v-for="f in (answer?.context||ctx.context).facts"><td>{{f.label}}</td><td>{{f.display}}</td><td>{{f.unit}}</td><td>{{f.window}}</td><td>{{f.n??'—'}}/{{f.expected_n??'—'}}</td><td>{{f.availability}}</td></tr></tbody></table></div><p v-for="text in (answer?.context||ctx.context).limitations" class="muted mt-3">{{text}}</p></details><div v-if="conversation.length>1" class="panel"><h2 class="font-semibold mb-4">Domande di questa sessione</h2><button v-for="r in conversation" class="text-left block text-green-400 py-2 text-sm" @click="answer=r">{{r.context.question}}</button></div></div></template>
